/* ON Mission 10.79.0 — unified operational Command Center */
import {workspaceFor} from './workspace-registry.js?v=16.10.91';
import {statusTone,displayValue,escapeHtml} from './ui-system.js?v=16.10.91';
import {ADMIN_WORKSPACE_GROUPS} from './workspace-registry.js?v=16.10.91';
import {openAdminDrawer} from './detail-drawer.js?v=16.10.91';
import {governanceReadiness,renderGovernanceReadiness} from './governance-readiness.js?v=16.10.91';
import {CONTROL_PLANE_AREAS,searchControlPlaneAreas} from './control-plane-model.js?v=16.10.91';

export async function renderCommandCenter({$,state,esc,loadCommandCenter,api,navigate}){
 const box=$('#view-overview');
 if(!box)return;
 if(typeof navigate!=='function')throw new TypeError('Canonical admin navigation is unavailable');
 box.innerHTML='<div class="cc-loading"><div class="eyebrow">SUPER ADMIN · CONTROL CENTER</div><h1 class="title">Composing platform situation…</h1><p class="sub">Reading canonical platform authorities. No default state is substituted.</p></div>';
 const fmt=v=>displayValue(v,{unknown:'UNAVAILABLE'});
 const tone=s=>statusTone(s);
 const openWorkItem=async(item)=>{const key=item?.action||'overview';if(key==='product-publisher'&&item?.resourceId){state.publisher={...(state.publisher||{}),launchId:Number(item.resourceId)||null,countryCode:item.countryCode||state.publisher?.countryCode||''};}if(key==='product-verification'&&item?.resourceId){state.productVerificationRunId=Number(item.resourceId)||null;}await navigate(key)};
 const action=(key,label='OPEN')=>`<button class="btn ${key===state.view?'primary':'muted'}" data-command-action="${escapeHtml(key)}">${escapeHtml(label)}</button>`;
 const metric=(label,value,meta,key,t='')=>`<button class="control-metric" data-command-action="${escapeHtml(key||'overview')}"><span>${escapeHtml(label)}</span><strong>${escapeHtml(fmt(value))}</strong><small>${escapeHtml(meta||'Open workspace')}</small>${t?`<em class="pill ${tone(t)}">${escapeHtml(t)}</em>`:''}</button>`;
 try{
  const cc=await loadCommandCenter(state.commandScope||{}); const osResponse=typeof api==='function'?await api('/api/platform/admin/operating-system'):null; const os=osResponse?.operatingSystem||{}; const s=cc.surface||{};const p=s.preview||{};const queue=s.queue||[];const lifecycle=s.lifecycle||[];const workspaceStates=Object.fromEntries((s.workspaceStates||[]).map(x=>[x.key,x]));const unavailable=cc.unavailableAuthorities||[];
  const governance=governanceReadiness(state.data||{});
  const categories=ADMIN_WORKSPACE_GROUPS.map(group=>({...group,workspaces:group.items.map(([label,key,description,authority,access,journey])=>({label,key,description,authority,access,journey,...(workspaceStates[key]||{})}))}));
  const stats=Object.fromEntries((s.stats||[]).map(x=>[x.key,x]));
  const attention=queue.slice(0,1);
  const working=cc.next||cc.now||{};
  const primaryAttention=attention.find(q=>q&&q.action)||null;
  const situationActionKey=primaryAttention?.action||working.actionKey||'product-health';
  const situationActionLabel=primaryAttention?.label==='Continue build'?'CONTINUE PRODUCT BUILD':(primaryAttention?.label?String(primaryAttention.label).toUpperCase():(working.actionLabel||'CONTINUE'));
  const platformHealth=s.status||'UNKNOWN';
  const securityStatus=unavailable.length||governance.overall==='UNAVAILABLE'?'CHECK':governance.overall==='ATTENTION'?'REVIEW':'PROTECTED';
  const workingTitle=working.title||p.productStatus||'Platform';
  const workingReason=working.reason||cc.now?.reason||'Continue the next governed platform step.';
  const readiness=p.readinessPercent==null?null:Number(p.readinessPercent);
  const categoryCards=categories.map(cat=>{
    const items=(cat.workspaces||[]).map(w=>({...(workspaceFor(w.action)||{}),...w}));
    return `<section class="control-area" id="command-category-${escapeHtml(cat.key)}"><header class="control-area-head"><div><span class="eyebrow">${escapeHtml(cat.label)}</span><h2>${escapeHtml(cat.label)}</h2><p class="sub">${escapeHtml(cat.description||'')}</p></div><button class="text-action" data-open-group="${escapeHtml(cat.key)}">VIEW ALL</button></header><div class="workspace-index-grid">${items.map(w=>`<article class="workspace-index-card"><div class="workspace-index-top"><span class="workspace-icon">${escapeHtml((w.label||'W').slice(0,1))}</span><div><h3>${escapeHtml(w.label||'Workspace')}</h3><span class="pill ${tone(w.status)}">${escapeHtml(w.status||'AVAILABLE')}</span></div></div><p>${escapeHtml(w.description||'')}</p><div class="workspace-governance-meta"><span>${escapeHtml(w.authority||'Canonical authority')}</span><span>${escapeHtml(w.access||'READ')} · ${escapeHtml(w.journey||'OPERATE')}</span></div><div class="workspace-index-foot"><span>${w.count==null?'No aggregate':escapeHtml(String(w.count))+' records'}</span><button class="btn muted" data-command-action="${escapeHtml(w.action||w.key||'overview')}">OPEN</button></div></article>`).join('')}</div></section>`;
  }).join('');
  box.innerHTML=`<div class="control-center">
    <header class="control-hero">
      <div><span class="eyebrow">ON MISSION · PLATFORM CONTROL</span><h1 class="title">Control Center</h1><p class="sub">One operational surface for situation, work, system health and governed platform navigation.</p></div>
      <div class="control-hero-actions"><span class="pill ${tone(platformHealth)}">${escapeHtml(platformHealth)}</span><span class="mini">v${escapeHtml(s.version||'—')}</span>${action('overview','REFRESH')}<button class="btn muted" id="objectiveToggleSpecialist" type="button" aria-expanded="false">PLATFORM DETAILS</button></div>
    </header>

    <section class="card section control-plane-home" aria-labelledby="control-plane-home-title">
      <header class="section-head"><div><span class="eyebrow">UNIFIED CONTROL PLANE</span><h2 id="control-plane-home-title">Where do you want to work?</h2><p class="sub">Eight clear areas. Each action opens its existing canonical workspace; permissions and mutations remain server-enforced.</p></div><button class="btn muted" data-command-action="resource-management">RESOURCE EXPLORER</button></header>
      <label class="control-plane-search-label" for="controlPlaneAreaSearch">Find a workspace or capability</label>
      <input id="controlPlaneAreaSearch" class="input control-plane-area-search" type="search" maxlength="120" autocomplete="off" placeholder="Try: Germany, consent, onboarding, database, ChatGPT, tenant…" />
      <div class="control-plane-search-actions"><span class="mini">Search here finds the right workspace. Search canonical records when you need a specific saved item.</span><button type="button" class="btn muted" id="controlPlaneSearchRecords">SEARCH CANONICAL RECORDS</button></div>
      <div class="control-plane-area-grid" id="controlPlaneAreaGrid">${CONTROL_PLANE_AREAS.map(area=>`<article class="control-plane-area-card" data-control-area-card="${escapeHtml(area.key)}"><div class="control-plane-area-icon" aria-hidden="true">${escapeHtml(area.label.slice(0,1))}</div><div class="control-plane-area-content"><h3>${escapeHtml(area.label)}</h3><p>${escapeHtml(area.description)}</p><button type="button" class="btn muted" data-control-plane-action="${escapeHtml(area.action)}">OPEN WORKSPACE <span aria-hidden="true">→</span></button></div></article>`).join('')}<div class="control-plane-no-results" id="controlPlaneNoResults" hidden>No matching workspace. Try a broader term or open Resource Explorer to search canonical records.</div></div>
    </section>

    <section class="card section objective-command" aria-labelledby="objective-command-title">
      <header class="section-head"><div><span class="eyebrow">OBJECTIVE WORKSPACE · ONE PLACE TO FINISH THE WORK</span><h2 id="objective-command-title">What outcome should ON MISSION achieve?</h2><p class="sub">Start once. Track the plan, provide missing information, review approvals, continue governed work and verify evidence here. Existing canonical services remain the only authorities.</p></div><span class="pill ok">GOVERNED · EVIDENCE-GATED</span></header>
      <form id="objectiveCommandForm" class="objective-command-form">
        <label class="field" for="objectiveCommandType">Objective type<select id="objectiveCommandType" class="input"><option value="platform">Platform objective</option><option value="market_launch">Prepare a market launch</option></select><small>Market launch plans use the canonical Market Factory registry and lifecycle.</small></label>
        <div id="objectiveMarketScope" class="objective-market-scope" hidden><label class="field">Country name<input id="objectiveMarketCountryName" class="input" maxlength="120" value="Germany" required></label><label class="field">ISO country code<input id="objectiveMarketCountryCode" class="input" maxlength="2" value="DE" pattern="[A-Za-z]{2}" required></label><label class="field">Product key<input id="objectiveMarketProductKey" class="input" maxlength="120" value="onmission-logistics" pattern="[A-Za-z0-9._-]+" required></label><label class="field">Sector code<input id="objectiveMarketSectorCode" class="input" maxlength="80" value="logistics" pattern="[A-Za-z0-9._-]+" required></label><p class="mini">This defines the planning scope only. It does not create a country, provision resources, establish residency, or activate a market.</p></div>
        <label class="field" for="objectiveCommandInput">Objective<textarea id="objectiveCommandInput" class="input" rows="3" maxlength="1200" required placeholder="Prepare Mission Execution for a production-ready logistics launch in Germany. Inspect blockers, prepare safe work, and show only decisions requiring my approval."></textarea><small>Keep the goal specific. Do not include passwords, tokens, or other secrets.</small></label>
        <div class="objective-command-controls"><label class="field" for="objectiveCommandMode">Planning mode<select id="objectiveCommandMode" class="input"><option value="inspect">Inspect and prepare plan</option><option value="readiness">Readiness assessment</option></select></label><button class="btn primary" id="objectivePrepareButton" type="submit">START OBJECTIVE</button></div>
      </form>
      <div id="objectivePlanResults" class="objective-plan-results" aria-live="polite"><div class="objective-empty"><b>Ready when you are.</b><span>Preparing a plan is read-only. Execution, publishing, resource changes and data migration remain behind their existing canonical authorization gates.</span></div></div>
    </section>

    <section class="card section objective-operations" aria-labelledby="objective-operations-title"><header class="section-head"><div><span class="eyebrow">UNIFIED OBJECTIVE OPERATIONS</span><h2 id="objective-operations-title">Plans, approvals &amp; results</h2><p class="sub">One view of persisted objectives and decisions requiring Super Admin authority. Missing data is shown as unavailable, never as an empty success.</p></div><button class="btn muted" id="objectiveRefreshInbox" type="button">REFRESH INBOX</button></header><div class="objective-inbox-grid"><section><h3>Pending approvals</h3><div id="objectiveGlobalApprovals" class="objective-global-list"><p class="sub">Loading approval authority…</p></div></section><section><h3>Recent objectives</h3><div id="objectiveRecentRuns" class="objective-global-list"><p class="sub">Loading objective history…</p></div></section></div></section>

    <details class="objective-specialist-details" id="objectiveSpecialistDetails"><summary>Platform status and specialist workspaces <span>Open only when you need administrative detail</span></summary><div class="objective-specialist-content"><section class="os-command-strip">
      <article class="os-command-health"><span class="eyebrow">PLATFORM POSTURE</span><strong>${escapeHtml(os.health||platformHealth)}</strong><small>${escapeHtml(os.unavailableAuthorities?.length?`${os.unavailableAuthorities.length} canonical authorities unavailable`:'Canonical platform reads available')}</small></article>
      <article><span class="eyebrow">ORGANIZATIONS</span><b>${fmt(os.platform?.organizations)}</b><small>Governed organizations</small></article>
      <article><span class="eyebrow">LIVE PRODUCTS</span><b>${fmt(os.platform?.liveProducts)}</b><small>Active country launches</small></article>
      <article><span class="eyebrow">MISSIONS</span><b>${fmt(os.platform?.activeMissions)}</b><small>Non-terminal missions</small></article>
      <article><span class="eyebrow">OPERATIONS</span><b>${fmt(os.platform?.operationsInFlight)}</b><small>Administrative operations in flight</small></article>
      <article><span class="eyebrow">SAFE MODE</span><button class="btn ${state.safeMode?'primary':'muted'}" id="toggleSafeMode">${state.safeMode?'READ-ONLY':'NORMAL'}</button><small>UI mutation guard</small></article>
    </section>

    <section class="situation-card card">
      <div class="situation-main"><span class="eyebrow">CURRENT SITUATION</span><h2>${escapeHtml(p.productStatus||'PLATFORM STATUS')}</h2><p class="situation-message">${escapeHtml(cc.now?.reason||'Platform state is being evaluated.')}</p><div class="situation-actions">${action(situationActionKey,attention.length?situationActionLabel:(working.actionLabel||'CONTINUE'))}</div></div>
      <div class="situation-state"><span class="state-dot ${tone(platformHealth)}"></span><b>${escapeHtml(platformHealth)}</b><small>${unavailable.length?`${unavailable.length} authority${unavailable.length===1?'':'ies'} unavailable`: 'Canonical platform reads available'}</small></div>
    </section>

    <section class="control-metrics">
      <div class="metric-group"><span class="eyebrow">PRODUCTS</span>${metric('Live products',stats['active-products']?.value,'Active country products','product-health',Number(stats['active-products']?.value||0)>0?'LIVE':'ATTENTION')}${metric('Readiness',readiness==null?null:`${readiness}%`,'Governed launch readiness','product-publisher',readiness===100?'READY':'ATTENTION')}</div>
      <div class="metric-group"><span class="eyebrow">OPERATIONS</span>${metric('Open work',stats['open-work']?.value,'Actionable or diagnostic work',working.actionKey||'overview',Number(stats['open-work']?.value||0)>0?'ATTENTION':'HEALTHY')}${metric('In flight',stats['in-flight']?.value,'Administrative operations','system-health',Number(stats['in-flight']?.value||0)>0?'IN PROGRESS':'HEALTHY')}</div>
      <div class="metric-group"><span class="eyebrow">SECURITY</span>${metric('Security posture',securityStatus,unavailable.length?'Review authority availability':'Protection boundaries operational','security',securityStatus)}${metric('Organizations',stats.organizations?.value,'Governed organizations','companies')}</div>
    </section>

    ${renderGovernanceReadiness(governance,{navigate})}

    <section class="control-work-grid">
      <section class="card section working-card"><header class="section-head"><div><span class="eyebrow">WORKING ON</span><h2>${escapeHtml(workingTitle)}</h2><p class="sub">${escapeHtml(workingReason)}</p></div><span class="pill ${tone(readiness===100?'READY':'IN PROGRESS')}">${readiness==null?'—':`${readiness}%`}</span></header><div class="working-progress"><div class="working-progress-bar"><span style="width:${Math.max(0,Math.min(100,readiness??0))}%"></span></div><div class="working-progress-meta"><span>Product preparation / platform readiness</span><b>${readiness==null?'UNAVAILABLE':`${readiness}%`}</b></div></div><div class="actions">${action(working.actionKey||'product-publisher',working.actionLabel||'CONTINUE')}</div></section>
      <section class="card section attention-card"><header class="section-head"><div><span class="eyebrow">CURRENT ACTION</span><h2>${attention.length?'One governed action':'Nothing requires action'}</h2><p class="sub">Only the highest-priority current action is presented. Other work remains discoverable through the workspace launcher.</p></div></header><div class="attention-list">${attention.map((q,i)=>`<article class="attention-row"><span class="attention-index">${i+1}</span><div><b>${escapeHtml(q.title||'Platform item')}</b><span>${escapeHtml(q.type||'work')} · ${escapeHtml(q.status||'')}</span></div><span class="pill ${tone(q.status)}">${escapeHtml(q.label||q.status||'OPEN')}</span><div class="attention-actions"><button class="btn muted" data-attention-detail="${i}">DETAILS</button><button class="btn primary" data-command-action="${escapeHtml(q.action||'overview')}">OPEN</button></div></article>`).join('')||'<div class="empty">No actionable work is currently projected.</div>'}</div></section>
    </section>

    <section class="card section release-card"><header class="section-head"><div><span class="eyebrow">RELEASE JOURNEY</span><h2>Product lifecycle</h2><p class="sub">The Control Center shows where governed product versions are in the release chain.</p></div><div class="actions">${action('product-publisher','OPEN MARKET FACTORY')}${action('product-verification','OPEN TEST LAB')}</div></header><div class="journey-track">${lifecycle.map((x,i)=>`<button class="journey-step ${x.count?'reached':''}" data-command-action="product-publisher"><span>${i+1}</span><b>${escapeHtml(x.label)}</b><strong>${escapeHtml(fmt(x.count))}</strong></button>`).join('')}</div></section>

    <section class="card section platform-context"><header class="section-head"><div><span class="eyebrow">PLATFORM CONTEXT</span><h2>Inspect a governed scope</h2><p class="sub">Context changes projections only. It never mutates a country, product, tenant or policy.</p></div><span class="pill ok">READ ONLY</span></header><div class="context-grid"><label class="field">Country<input id="commandCountry" class="input" maxlength="2" value="${escapeHtml(cc.productLens?.countryCode||'')}" placeholder="DE" autocomplete="off"></label><label class="field">Sector<input id="commandSector" class="input" maxlength="80" value="${escapeHtml(cc.productLens?.sectorCode||'')}" placeholder="logistics" autocomplete="off"></label><div class="context-result"><span>Selected scope</span><b>${escapeHtml(cc.productLens?.productState||'PLATFORM')}</b><small>${escapeHtml(cc.productLens?.result||'Select a country and sector.')}</small></div><div class="actions"><button class="btn primary" id="commandApplyScope">APPLY CONTEXT</button><button class="btn muted" id="commandClearScope">CLEAR</button></div></div></section>

    <section class="control-explorer"><header class="control-area-head"><div><span class="eyebrow">EXPLORE PLATFORM</span><h2>Workspaces</h2><p class="sub">One registry, one route per capability. Use the launcher for fast access.</p></div><button class="btn primary" data-open-command-palette>OPEN WORKSPACE LAUNCHER</button></header><div class="explorer-tabs">${categories.map((cat,i)=>`<button class="explorer-tab ${i===0?'active':''}" data-explorer-tab="${escapeHtml(cat.key)}">${escapeHtml(cat.label)}</button>`).join('')}</div><div class="explorer-panels">${categoryCards}</div></section>

    <section class="card section activity-card"><header class="section-head"><div><span class="eyebrow">RECENT ACTIVITY</span><h2>Administrative operations</h2><p class="sub">Evidence is shown here; canonical operation services own state transitions.</p></div><button class="btn muted" data-command-action="system-health">OPEN OPERATIONS</button><button class="btn muted" id="openCertification">OPEN CERTIFICATION</button></header><div class="activity-list">${(cc.recentOperations||[]).slice(0,8).map(o=>`<article class="activity-row"><div><b>${escapeHtml(o.action_code||'Administrative operation')}</b><span>${escapeHtml(o.resource_type||'resource')} ${o.resource_id?`#${escapeHtml(o.resource_id)}`:''}</span></div><span class="pill ${tone(o.status)}">${escapeHtml(o.status||'UNKNOWN')}</span><time>${escapeHtml(o.started_at||'—')}</time></article>`).join('')||'<div class="empty">No administrative operations recorded.</div>'}</div></section>

    ${unavailable.length?`<section class="card section authority-card"><header class="section-head"><div><span class="eyebrow">AUTHORITY AVAILABILITY</span><h2>Some canonical reads are unavailable</h2><div class="mini">AUTHORITY UNAVAILABLE is a distinct platform state; no certification or product result is inferred.</div><p class="sub">No empty values were substituted. Resolve the owning authority before treating the platform as healthy.</p></div><span class="pill bad">${unavailable.length} UNAVAILABLE</span></header><div class="authority-list">${unavailable.map(a=>`<div><b>${escapeHtml(a.authority)}</b><span>${escapeHtml(a.code||'AUTHORITY_UNAVAILABLE')}</span></div>`).join('')}</section>`:''}
    </div></details>
  </div>`;

  const areaSearch=$('#controlPlaneAreaSearch'),areaGrid=$('#controlPlaneAreaGrid'),areaEmpty=$('#controlPlaneNoResults');
  const filterControlAreas=()=>{const matches=new Set(searchControlPlaneAreas(areaSearch?.value||'').map(x=>x.key));let visible=0;areaGrid?.querySelectorAll('[data-control-area-card]').forEach(card=>{const show=matches.has(card.dataset.controlAreaCard);card.hidden=!show;if(show)visible++;});if(areaEmpty)areaEmpty.hidden=visible!==0;};
  areaSearch?.addEventListener('input',filterControlAreas);
  $('#controlPlaneSearchRecords')?.addEventListener('click',async()=>{const query=String(areaSearch?.value||'').trim();state.resourceSearchQuery=query;await openWorkItem({action:'resource-management'});});
  box.querySelectorAll('[data-control-plane-action]').forEach(button=>button.addEventListener('click',()=>openWorkItem({action:button.dataset.controlPlaneAction})));
  const renderObjectiveInbox=async()=>{const approvalsNode=$('#objectiveGlobalApprovals'),runsNode=$('#objectiveRecentRuns');if(!approvalsNode||!runsNode)return;approvalsNode.innerHTML='<p class="sub">Refreshing approvals…</p>';runsNode.innerHTML='<p class="sub">Refreshing objectives…</p>';try{const [a,o]=await Promise.all([api('/api/platform/admin/objectives/approvals'),api('/api/platform/admin/objectives')]);const approvals=Array.isArray(a?.approvals)?a.approvals:null;const objectives=Array.isArray(o?.objectives)?o.objectives:null;if(approvals===null)throw new Error('Approval authority returned an invalid projection');if(objectives===null)throw new Error('Objective authority returned an invalid projection');approvalsNode.innerHTML=approvals.length?approvals.slice(0,8).map(x=>`<article class="objective-global-row"><div><b>${escapeHtml(x.objective_text||'Objective')}</b><p>${escapeHtml(x.step_title||'Decision')} · ${escapeHtml(x.authority_code||'canonical authority')}</p><small>${escapeHtml(x.approval_id)} · revision ${escapeHtml(x.revision)}</small></div><span class="pill warn">PENDING</span></article>`).join(''):'<p class="sub">No pending approvals.</p>';runsNode.innerHTML=objectives.length?objectives.slice(0,8).map(x=>`<article class="objective-global-row"><div><b>${escapeHtml(x.objective_text||'Objective')}</b><p>${escapeHtml(x.objective_id)} · ${escapeHtml(x.latest_run_id||'No run')}</p></div><span class="pill ${tone(x.status)}">${escapeHtml(x.status||'UNKNOWN')}</span>${x.latest_run_id?`<button class="btn muted" type="button" data-objective-open-run="${escapeHtml(x.latest_run_id)}">OPEN</button>`:`<button class="btn muted" type="button" disabled title="This objective has no persisted run to open">NO RUN</button>`}</article>`).join(''):'<p class="sub">No objectives have been recorded yet.</p>';runsNode.querySelectorAll('[data-objective-open-run]').forEach(b=>b.addEventListener('click',async()=>{if(!b.dataset.objectiveOpenRun)return;try{const fresh=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(b.dataset.objectiveOpenRun)}`);await renderObjectiveRun(fresh.run);$('#objectiveCommandForm')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){runsNode.insertAdjacentHTML('afterbegin',`<p class="notice">Objective could not be opened: ${escapeHtml(e.message||'Authority unavailable')}</p>`);}}));}catch(e){approvalsNode.innerHTML=`<p class="notice">Approval inbox unavailable: ${escapeHtml(e.message||'Canonical authority unavailable')}</p>`;runsNode.innerHTML=`<p class="notice">Objective history unavailable: ${escapeHtml(e.message||'Canonical authority unavailable')}</p>`;}};
  $('#objectiveRefreshInbox')?.addEventListener('click',renderObjectiveInbox);void renderObjectiveInbox();
  const objectiveForm=$('#objectiveCommandForm');
  const renderObjectiveRun=async(run)=>{
    const result=$('#objectivePlanResults');if(!result)return;
    try{if(run?.run_id)localStorage.setItem('onmission_active_objective_run',String(run.run_id));}catch{/* storage is optional; canonical run remains server-persisted */}
    const steps=Array.isArray(run?.steps)?run.steps:[];const approvalsResponse=await api('/api/platform/admin/objectives/approvals').catch(()=>({approvals:[]}));const approvals=Array.isArray(approvalsResponse?.approvals)?approvalsResponse.approvals:[];
    result.innerHTML=`<div class="objective-plan-head"><div><span class="eyebrow">PERSISTED OBJECTIVE PLAN</span><h3>${escapeHtml(run.objective_text||'Objective')}</h3><p>Objective ID ${escapeHtml(run.objective_id||'—')} · Run ID ${escapeHtml(run.run_id||'—')} · revision ${escapeHtml(run.revision??'—')}</p></div><span class="pill ${tone(run.status)}">${escapeHtml(run.status||'UNKNOWN')}</span></div>${run.plan?.marketLaunch?`<section class="objective-market-summary"><div><span class="eyebrow">MARKET SCOPE · CANONICAL READ</span><h3>${escapeHtml(run.plan.marketLaunch.countryName)} (${escapeHtml(run.plan.marketLaunch.countryCode)})</h3><p>Product <code>${escapeHtml(run.plan.marketLaunch.productKey)}</code> · sector <code>${escapeHtml(run.plan.marketLaunch.sectorCode)}</code></p><p>${run.plan.marketLaunch.existingPackage?`Existing package ${escapeHtml(run.plan.marketLaunch.existingPackage.packageKey)} · latest version ${escapeHtml(run.plan.marketLaunch.existingPackage.latestVersion||'—')} · ${escapeHtml(run.plan.marketLaunch.existingPackage.latestVersionStatus||'UNKNOWN')}`:'No existing package found for this product/country. Market Factory must create the first governed package.'}</p><small>Read at ${escapeHtml(run.plan.marketLaunch.observedAt)}. Residency and launch readiness are not inferred from this scope.</small></div><button class="btn primary" type="button" id="objectiveOpenMarketFactory">OPEN MARKET FACTORY</button></section>`:''}<section class="objective-contract-panel"><div class="eyebrow">OBJECTIVE COMPLETION CONTRACT</div><h3>Define what “done” means</h3><p class="sub">Confirm the objective scope, measurable success conditions and evidence needed to prove completion. No objective step can execute until this contract is confirmed and the canonical situation is reassessed.</p><p class="mini">Contract status: <b>${escapeHtml(run.plan?.completionContract?.status||'DRAFT')}</b> · policy: all criteria require independent evidence.</p><form id="objectiveContractForm" class="objective-command-form"><label class="field" for="objectiveContractCriteria">Success criteria (one per line)<textarea id="objectiveContractCriteria" class="input" rows="3" maxlength="10000" required placeholder="e.g. Germany market package has a verified LIVE release
Delivery mission reaches verified OUTCOME"></textarea></label><label class="field" for="objectiveContractEvidence">Required evidence (one per line)<textarea id="objectiveContractEvidence" class="input" rows="3" maxlength="10000" required placeholder="e.g. Market Factory release verification evidence
Mission outcome and recovery evidence"></textarea></label><label class="field" for="objectiveContractConstraints">Constraints (one per line, optional)<textarea id="objectiveContractConstraints" class="input" rows="2" maxlength="10000" placeholder="e.g. No customer data changes without approval
Invite-only pilot"></textarea></label><label class="field checkbox-field"><input id="objectiveContractScopeConfirmed" type="checkbox" required> I confirm the objective and displayed scope are correct.</label><button class="btn primary" id="objectiveConfirmContract" type="submit">CONFIRM COMPLETION CONTRACT</button></form><p class="mini">Criteria are not treated as satisfied merely because a task disappears or an executor returns success. The owning canonical authority must provide evidence.</p></section><section class="objective-gap-panel"><div class="eyebrow">GAP &amp; DEPENDENCY INTELLIGENCE</div><h3>What remains before this objective can succeed?</h3><p class="sub">Calculate gaps from the latest canonical platform context, the confirmed completion contract and existing queue. This assessment proposes order and ownership; it does not create records or execute work.</p>${run.plan?.gapAssessment?`<p class="mini">Last assessment: ${escapeHtml(run.plan.gapAssessment.status)} · ${escapeHtml(run.plan.gapAssessment.gapCount)} gaps · observed ${escapeHtml(run.plan.gapAssessment.observedAt||'—')}</p><div class="objective-plan-steps">${(run.plan.gapAssessment.gaps||[]).map(g=>`<article class="objective-plan-step"><div class="objective-step-copy"><b>${escapeHtml(g.title)}</b><p>${escapeHtml(g.reason||g.resolution||'Review owning authority.')}</p><small>${escapeHtml(g.kind)} · ${escapeHtml(g.source)} · depends on ${(g.dependsOn||[]).map(escapeHtml).join(', ')||'none identified'}</small>${['REQUIRED_EVIDENCE','SUCCESS_CRITERION_UNVERIFIED'].includes(g.kind)?`<form class="objective-preparation-form objective-command-form" data-objective-preparation="${escapeHtml(g.gapId)}"><label class="field">Evidence reference / proposed source<input class="input" name="evidenceReference" maxlength="500" required placeholder="Canonical record ID, evidence reference or source location"></label><label class="field">Owning authority<input class="input" name="sourceAuthority" maxlength="120" required placeholder="e.g. Market Factory or mission outcome authority"></label><label class="field">Preparation notes<textarea class="input" name="notes" maxlength="1200" rows="2" placeholder="Explain what this supports; do not include secrets."></textarea></label><label class="field">Reuse existing canonical resource ID (optional)<input class="input" name="reuseResourceId" maxlength="160" placeholder="Must match a resource already present in canonical queue"></label><button class="btn muted" type="submit">VALIDATE &amp; PREPARE PROPOSAL</button><small>Prepared proposals are not canonical records and do not verify success.</small></form>`:''}</div><span class="pill ${tone(g.status)}">${escapeHtml(g.preparationStatus||g.status)}</span></article>`).join('')||'<p class="sub">No unverified gaps were discovered in this assessment. Completion still requires independent evidence for every success criterion.</p>'}</div>`:'<p class="mini">No gap assessment has been recorded for this revision yet.</p>'}<button class="btn primary" id="objectiveAssessGaps" type="button">CALCULATE REMAINING WORK</button><p class="mini">An unavailable authority is a blocker, not an empty result. Every proposed resolution must use the owning canonical workflow.</p></section><section class="objective-outcome-panel"><div class="eyebrow">OUTCOME &amp; RECOVERY LOOP</div><h3>Reconcile actual effects and evidence</h3><p class="sub">Reconcile persisted step evidence with fresh canonical context. Failed or uncertain effects require recovery; missing evidence remains unverified. Reconciliation never declares success merely because work stopped.</p>${run.plan?.outcomeAssessment?`<p class="mini">Latest outcome: <b>${escapeHtml(run.plan.outcomeAssessment.status)}</b> · ${escapeHtml(run.plan.outcomeAssessment.completedStepCount||0)} of ${escapeHtml(run.plan.outcomeAssessment.totalStepCount||0)} steps marked complete · observed ${escapeHtml(run.plan.outcomeAssessment.observedAt||'—')}</p><p>${escapeHtml(run.plan.outcomeAssessment.completionReason||'')}</p>${(run.plan.outcomeAssessment.recoveryPlan||[]).map(r=>`<article class="objective-plan-step"><div class="objective-step-copy"><b>${escapeHtml(r.title)}</b><p>${escapeHtml(r.reason)}</p><small>Recommended: ${escapeHtml(r.recommendedAction)} · automatic retry: no</small></div><span class="pill ${tone(r.status)}">${escapeHtml(r.status)}</span></article>`).join('')||'<p class="mini">No recovery item was detected in the recorded step evidence. Completion still depends on verified contract evidence.</p>'}`:'<p class="mini">No outcome reconciliation has been recorded for this objective run.</p>'}<button class="btn primary" id="objectiveReconcileOutcome" type="button">RECONCILE OUTCOME &amp; RECOVERY</button>${run.plan?.outcomeAssessment?.status==='COMPLETION_CANDIDATE'?'<button class="btn primary" id="objectiveConfirmCompletion" type="button">CONFIRM VERIFIED COMPLETION</button>':''}<p class="mini">Completion requires fresh canonical context, trusted evidence for every criterion, no unresolved recovery and explicit Super Admin step-up confirmation.</p></section><div class="objective-plan-steps">${steps.map((step,i)=>`<article class="objective-plan-step"><span class="objective-step-number">${i+1}</span><div class="objective-step-copy"><b>${escapeHtml(step.title)}</b><p>${escapeHtml(step.description)}</p><small>Authority: ${escapeHtml(step.authority_code)} · Attempts: ${escapeHtml(step.attempt_count||0)}</small></div><span class="pill ${tone(step.status)}">${escapeHtml(step.status)}</span></article>`).join('')}</div><section class="objective-input-panel"><div class="eyebrow">OBJECTIVE CONTINUATION</div><h3>Provide the next missing information</h3><p class="sub">Add a fact, decision, requirement or correction. Mission Execution records it against this objective, then requires reassessment against canonical authorities before the next action. This does not directly change tenant or market data.</p><form id="objectiveInputForm" class="objective-command-form"><label class="field" for="objectiveInputKey">Information type<input id="objectiveInputKey" class="input" maxlength="80" pattern="[A-Za-z][A-Za-z0-9_.-]+" placeholder="e.g. legal_reviewer" required></label><label class="field" for="objectiveInputLabel">What is this information?<input id="objectiveInputLabel" class="input" maxlength="120" placeholder="e.g. Legal review contact" required></label><label class="field" for="objectiveInputValue">Enter the data or decision<textarea id="objectiveInputValue" class="input" rows="3" maxlength="4000" placeholder="Provide the missing information. Do not enter passwords, tokens or secrets." required></textarea></label><button class="btn primary" id="objectiveSubmitInput" type="submit">SUBMIT DATA &amp; REASSESS</button></form><p class="mini">Submitted information is audited as objective context. Canonical authorities remain the source of truth for actual domain state.</p></section><div class="notice"><b>Execution boundary:</b> the objective, plan, steps and event history are persisted. Market preparation coordinates the existing Market Factory; it does not bypass package validation, step-up authorization, immutable releases, runtime verification or activation gates.</div><section class="objective-approval-inbox"><div class="eyebrow">GOVERNED APPROVAL INBOX</div><h3>Decisions requiring your authority</h3>${approvals.length?approvals.map(a=>`<article class="objective-plan-step"><div class="objective-step-copy"><b>${escapeHtml(a.objective_text)}</b><p>${escapeHtml(a.step_title)} — ${escapeHtml(a.requested_reason)}</p><small>Approval ${escapeHtml(a.approval_id)} · revision ${escapeHtml(a.revision)}</small></div><div class="objective-approval-actions"><button class="btn muted" type="button" data-objective-approval="${escapeHtml(a.approval_id)}" data-decision="APPROVED" data-revision="${escapeHtml(a.revision)}">APPROVE</button><button class="btn muted" type="button" data-objective-approval="${escapeHtml(a.approval_id)}" data-decision="REJECTED" data-revision="${escapeHtml(a.revision)}">REJECT</button></div></article>`).join(''):'<p class="sub">No pending objective approvals were returned.</p>'}</section><div class="objective-plan-actions"><button class="btn muted" type="button" id="objectiveCopyPlan">COPY PLAN SUMMARY</button><button class="btn muted" type="button" id="objectiveRefreshRun">REFRESH STATUS</button><button class="btn primary" type="button" id="objectiveExecuteNext">EXECUTE NEXT SAFE STEP</button></div>`;
    result.querySelectorAll('[data-objective-preparation]')?.forEach(form=>form.addEventListener('submit',async(event)=>{event.preventDefault();const submit=form.querySelector('button[type="submit"]');if(!run?.run_id||!submit)return;const data=new FormData(form);const fields={evidenceReference:String(data.get('evidenceReference')||'').trim(),sourceAuthority:String(data.get('sourceAuthority')||'').trim(),notes:String(data.get('notes')||'').trim(),reuseResourceId:String(data.get('reuseResourceId')||'').trim()};if(fields.evidenceReference.length<3||fields.sourceAuthority.length<2)return;submit.disabled=true;submit.textContent='VALIDATING PREPARATION…';try{const prepared=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/preparations`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{gapId:form.dataset.objectivePreparation,fields,expectedRevision:Number(run.revision)}});if(!prepared?.success||prepared.canonicalMutationPerformed!==false)throw new Error('Preparation proposal was not safely recorded.');await renderObjectiveRun(prepared.run);await renderObjectiveInbox();const note=document.createElement('div');note.className='notice';note.textContent='Preparation proposal validated and recorded. The owning canonical authority must still accept the data and verify its effect; no canonical record was created.';result.prepend(note);}catch(e){const note=document.createElement('div');note.className='notice';note.textContent=`Preparation stopped safely: ${e.message||'Input validation failed'}`;result.prepend(note);}finally{submit.disabled=false;submit.textContent='VALIDATE & PREPARE PROPOSAL';}}));
    $('#objectiveConfirmCompletion')?.addEventListener('click',async(event)=>{const button=event.currentTarget;if(!run?.run_id||!window.confirm('Confirm this objective as complete? The system will recheck canonical authority availability, evidence freshness, all success criteria and every planned step.'))return;button.disabled=true;button.textContent='VERIFYING COMPLETION…';try{const completed=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/complete`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{expectedRevision:Number(run.revision)}});if(!completed?.success||!completed?.completed)throw new Error('Verified completion was not accepted.');await renderObjectiveRun(completed.run);await renderObjectiveInbox();const note=document.createElement('div');note.className='notice';note.textContent='Objective marked complete after explicit confirmation and canonical evidence checks.';result.prepend(note);}catch(e){const note=document.createElement('div');note.className='notice';note.textContent=`Completion denied safely: ${e.message||'Verification requirements not satisfied'}`;result.prepend(note);}finally{button.disabled=false;button.textContent='CONFIRM VERIFIED COMPLETION';}});
    $('#objectiveReconcileOutcome')?.addEventListener('click',async(event)=>{const button=event.currentTarget;if(!run?.run_id)return;button.disabled=true;button.textContent='RECONCILING OUTCOME…';try{const reconciled=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/outcome/reconcile`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{expectedRevision:Number(run.revision)}});if(!reconciled?.success||!reconciled?.outcome)throw new Error('Outcome reconciliation did not complete.');await renderObjectiveRun(reconciled.run);await renderObjectiveInbox();const note=document.createElement('div');note.className='notice';note.textContent=reconciled.outcome.status==='RECOVERY_REQUIRED'?'Outcome reconciliation found failed or uncertain work. Follow the recovery plan and reconcile effects before any retry.':reconciled.outcome.status==='BLOCKED'?'Canonical authority unavailable. Outcome remains blocked until the owning authority is restored.':reconciled.outcome.status==='COMPLETION_CANDIDATE'?'All contract evidence appears present. A separate completion confirmation is still required.':'Outcome is waiting for independently verified canonical evidence; no success was inferred.';result.prepend(note);}catch(e){const note=document.createElement('div');note.className='notice';note.textContent=`Outcome reconciliation stopped safely: ${e.message||'Canonical outcome unavailable'}`;result.prepend(note);}finally{button.disabled=false;button.textContent='RECONCILE OUTCOME & RECOVERY';}});
    $('#objectiveAssessGaps')?.addEventListener('click',async(event)=>{const button=event.currentTarget;if(!run?.run_id)return;button.disabled=true;button.textContent='ASSESSING CANONICAL GAPS…';try{const assessed=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/gaps`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{expectedRevision:Number(run.revision)}});if(!assessed?.success||!assessed?.assessment)throw new Error('Gap assessment did not complete.');await renderObjectiveRun(assessed.run);await renderObjectiveInbox();const note=document.createElement('div');note.className='notice';note.textContent=assessed.assessment.status==='BLOCKED'?'Gap assessment found an unavailable canonical authority. Resolve the owning authority before proceeding.':`${assessed.assessment.gapCount} gap(s) recorded from canonical context. Review the dependency order; nothing was executed.`;result.prepend(note);}catch(e){const note=document.createElement('div');note.className='notice';note.textContent=`Gap assessment stopped safely: ${e.message||'Canonical context unavailable'}`;result.prepend(note);}finally{button.disabled=false;button.textContent='CALCULATE REMAINING WORK';}});
    $('#objectiveContractForm')?.addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget;const button=$('#objectiveConfirmContract');if(!run?.run_id)return;const lines=id=>String($(id)?.value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const successCriteria=lines('#objectiveContractCriteria');const evidenceRequirements=lines('#objectiveContractEvidence');const constraints=lines('#objectiveContractConstraints');if(!successCriteria.length||!evidenceRequirements.length||!$('#objectiveContractScopeConfirmed')?.checked)return;button.disabled=true;button.textContent='CONFIRMING CONTRACT…';try{const saved=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/contract`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{successCriteria,evidenceRequirements,constraints,scopeConfirmed:true,expectedRevision:Number(run.revision)}});if(!saved?.success||!saved?.reassessmentRequired)throw new Error('Completion contract was not confirmed.');const reassessed=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/reassess`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{expectedRevision:Number(saved.run.revision)}});if(!reassessed?.success)throw new Error('Canonical reassessment did not complete.');await renderObjectiveRun(reassessed.run);await renderObjectiveInbox();const note=document.createElement('div');note.className='notice';note.textContent='Completion contract confirmed. Canonical context has been refreshed; criteria remain unverified until evidence is returned by their owning authorities.';result.prepend(note);}catch(e){const note=document.createElement('div');note.className='notice';note.textContent=`Contract not confirmed: ${e.message||'Completion contract unavailable'}`;result.prepend(note);}finally{button.disabled=false;button.textContent='CONFIRM COMPLETION CONTRACT';}});
    $('#objectiveInputForm')?.addEventListener('submit',async(event)=>{event.preventDefault();const form=event.currentTarget;const button=$('#objectiveSubmitInput');const key=String($('#objectiveInputKey')?.value||'').trim().toLowerCase();const label=String($('#objectiveInputLabel')?.value||'').trim();const value=String($('#objectiveInputValue')?.value||'').trim();if(!/^[a-z][a-z0-9_.-]{1,79}$/.test(key)||label.length<2||!value||!run?.run_id)return;button.disabled=true;button.textContent='SUBMITTING & REASSESSING…';try{const submitted=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/input`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{key,label,value,expectedRevision:Number(run.revision)}});if(!submitted?.success||!submitted?.reassessmentRequired)throw new Error('Objective input was not accepted for reassessment.');form.reset();const reassessed=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/reassess`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{expectedRevision:Number(submitted.run.revision)}});if(!reassessed?.success||!reassessed?.reassessed)throw new Error('Fresh canonical reassessment did not complete.');await renderObjectiveRun(reassessed.run);await renderObjectiveInbox();const note=document.createElement('div');note.className='notice';note.textContent=reassessed.status==='BLOCKED'?'Input recorded, but a canonical authority is unavailable. The objective remains blocked until the owning authority is restored.':'Input recorded and canonical situation reassessed. Review the refreshed gaps before choosing the next governed action.';result.prepend(note);}catch(e){const note=document.createElement('div');note.className='notice';note.textContent=`Input not accepted: ${e.message||'Objective authority unavailable'}`;result.prepend(note);}finally{button.disabled=false;button.textContent='SUBMIT DATA & REASSESS';}});
    $('#objectiveOpenMarketFactory')?.addEventListener('click',()=>navigate('product-publisher'));
    $('#objectiveCopyPlan')?.addEventListener('click',()=>{const summary=[`Objective: ${run.objective_text}`,`Objective ID: ${run.objective_id}`,`Run ID: ${run.run_id}`,`Status: ${run.status}`,...steps.map((x,i)=>`${i+1}. ${x.title} — ${x.status} [${x.authority_code}]`),'Execution only occurs through registered canonical executor adapters.'].join('\n');navigator.clipboard?.writeText(summary).catch(()=>{});});
    $('#objectiveRefreshRun')?.addEventListener('click',async()=>{try{const fresh=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}`);await renderObjectiveRun(fresh.run)}catch(e){result.insertAdjacentHTML('afterbegin',`<div class="notice">Status refresh failed: ${escapeHtml(e.message||'Authority unavailable')}</div>`);}});
    $('#objectiveExecuteNext')?.addEventListener('click',async(buttonEvent)=>{const button=buttonEvent.currentTarget;if(!run?.run_id||!Number.isInteger(Number(run.revision)))return;button.disabled=true;button.textContent='SELECTING GOVERNED NEXT STEP…';try{const selected=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/continuation`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{expectedRevision:Number(run.revision)}});if(!selected?.success||!selected?.continuation)throw new Error('No governed continuation decision was returned.');if(selected.continuation.status!=='READY_TO_EXECUTE_ONE_STEP'){await renderObjectiveRun(selected.run);await renderObjectiveInbox();const note=document.createElement('div');note.className='notice';note.textContent=`Next step: ${selected.continuation.status} — ${selected.continuation.reason}`;result.prepend(note);return;}if(!window.confirm(`Execute one registered step: ${selected.continuation.step?.title||selected.continuation.step?.code}? Step-up authorization and canonical executor gates still apply.`)){await renderObjectiveRun(selected.run);return;}button.textContent='EXECUTING ONE STEP…';await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}/execute`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{expectedRevision:Number(selected.run.revision)}});const fresh=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}`);await renderObjectiveRun(fresh.run);await renderObjectiveInbox();}catch(e){result.insertAdjacentHTML('afterbegin',`<div class="notice">Continuation stopped safely: ${escapeHtml(e.message||'Canonical executor unavailable')}</div>`);button.disabled=false;button.textContent='EXECUTE NEXT SAFE STEP';}finally{button.disabled=false;button.textContent='EXECUTE NEXT SAFE STEP';}});
    result.querySelectorAll('[data-objective-approval]').forEach(button=>button.addEventListener('click',async()=>{const reason=window.prompt('Provide a reason for this approval decision (minimum 8 characters):');if(!reason||reason.trim().length<8)return;button.disabled=true;try{await api(`/api/platform/admin/objective-approvals/${encodeURIComponent(button.dataset.objectiveApproval)}/decide`,{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{decision:button.dataset.decision,reason:reason.trim(),expectedRevision:Number(button.dataset.revision)}});const fresh=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(run.run_id)}`);await renderObjectiveRun(fresh.run)}catch(e){button.disabled=false;result.insertAdjacentHTML('afterbegin',`<div class="notice">Decision was not recorded: ${escapeHtml(e.message||'Approval unavailable')}</div>`);}}));
  };
  $('#objectiveToggleSpecialist')?.addEventListener('click',()=>{const panel=$('#objectiveSpecialistDetails');if(!panel)return;panel.open=!panel.open;$('#objectiveToggleSpecialist').setAttribute('aria-expanded',String(panel.open));$('#objectiveToggleSpecialist').textContent=panel.open?'HIDE PLATFORM DETAILS':'PLATFORM DETAILS';if(panel.open)panel.scrollIntoView({behavior:'smooth',block:'start'});});
  try{const activeRunId=localStorage.getItem('onmission_active_objective_run');if(activeRunId){const active=await api(`/api/platform/admin/objective-runs/${encodeURIComponent(activeRunId)}`);if(active?.run)await renderObjectiveRun(active.run);}}catch(error){const result=$('#objectivePlanResults');if(result)result.insertAdjacentHTML('afterbegin',`<p class="mini">Saved objective could not be resumed from the current session: ${escapeHtml(error?.message||'canonical run unavailable')}. Use Recent objectives to reopen it. No status was inferred.</p>`);}
  const objectiveType=$('#objectiveCommandType'),marketScope=$('#objectiveMarketScope'),objectiveInput=$('#objectiveCommandInput');
  const syncObjectiveType=()=>{const market=objectiveType?.value==='market_launch';if(marketScope)marketScope.hidden=!market;marketScope?.querySelectorAll('input').forEach(input=>{input.required=market;});if(objectiveInput&&market&&(!objectiveInput.value.trim()||objectiveInput.value.trim().startsWith('Prepare Mission Execution for a production-ready logistics launch')))objectiveInput.value='Prepare the Germany logistics market for a controlled production launch. Inspect the existing package, resolve blockers, and show only decisions requiring my approval.';};
  objectiveType?.addEventListener('change',syncObjectiveType);syncObjectiveType();
  let pendingObjectiveIntent=null;
  objectiveForm?.addEventListener('submit',async(event)=>{
    event.preventDefault();const input=$('#objectiveCommandInput');const result=$('#objectivePlanResults');const submit=$('#objectivePrepareButton');const objective=String(input?.value||'').trim();if(!objective||!result)return;if(objective.length>1200){result.innerHTML='<div class="notice">Objective is too long. Keep it under 1,200 characters.</div>';return;}
    submit.disabled=true;submit.textContent='PREPARING…';result.innerHTML='<div class="objective-empty"><b>Inspecting canonical authorities and saving the objective…</b><span>The server will persist a stable objective/run ID, a revision-guarded plan, evidence and approval requests. No generic text is executed as an action.</span></div>';
    try{const mode=$('#objectiveCommandMode')?.value||'inspect';const scope={...(state.commandScope||{})};if($('#objectiveCommandType')?.value==='market_launch'){scope.marketLaunch={countryName:String($('#objectiveMarketCountryName')?.value||'').trim(),countryCode:String($('#objectiveMarketCountryCode')?.value||'').trim().toUpperCase(),productKey:String($('#objectiveMarketProductKey')?.value||'').trim().toLowerCase(),sectorCode:String($('#objectiveMarketSectorCode')?.value||'').trim().toLowerCase()};if(scope.marketLaunch.countryName.length<2||!/^[A-Z]{2}$/.test(scope.marketLaunch.countryCode)||!/^[a-z0-9][a-z0-9._-]{1,119}$/.test(scope.marketLaunch.productKey)||!/^[a-z0-9][a-z0-9._-]{1,79}$/.test(scope.marketLaunch.sectorCode))throw new Error('Enter a valid country, ISO code, product key and sector code.');}const intent={objective,mode,scope};const signature=JSON.stringify(intent);if(!pendingObjectiveIntent||pendingObjectiveIntent.signature!==signature)pendingObjectiveIntent={signature,key:crypto.randomUUID()};const prepared=await api('/api/platform/admin/objectives/prepare',{method:'POST',headers:{'X-ONM-Explicit-Governed-Action':'1'},body:{...intent,idempotencyKey:pendingObjectiveIntent.key}});if(!prepared?.run)throw new Error('The objective service did not return a persisted run.');pendingObjectiveIntent=null;await renderObjectiveRun(prepared.run);}
    catch(error){result.innerHTML=`<div class="notice"><b>Objective plan unavailable.</b> The server could not safely persist and prepare the objective. No executable action was inferred. <span>${escapeHtml(error?.message||'Objective authority unavailable')}</span></div>`;}
    finally{submit.disabled=false;submit.textContent='START OBJECTIVE';}
  });
  const apply=()=>{state.commandScope={countryCode:$('#commandCountry')?.value.trim().toUpperCase()||'',sectorCode:$('#commandSector')?.value.trim().toLowerCase()||''};navigate('overview')};
  $('#toggleSafeMode')?.addEventListener('click',()=>{state.safeMode=!Boolean(state.safeMode);localStorage.setItem('onmission_super_admin_safe_mode',state.safeMode?'1':'0');navigate('overview')});
  $('#commandApplyScope')?.addEventListener('click',apply);
  $('#commandClearScope')?.addEventListener('click',()=>{state.commandScope={};navigate('overview')});
  box.querySelectorAll('[data-command-action]').forEach(b=>b.addEventListener('click',()=>openWorkItem({action:b.dataset.commandAction})));
  box.querySelectorAll('[data-governance-open]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.governanceOpen)));
  box.querySelectorAll('[data-attention-detail]').forEach(b=>b.addEventListener('click',()=>{const q=attention[Number(b.dataset.attentionDetail)];if(!q)return;const ws=workspaceStates[q.action]||{};openAdminDrawer({title:q.title||'Platform item',eyebrow:q.type?String(q.type).toUpperCase():'PLATFORM DETAIL',summary:q.reason||'Read-only operational detail. State transitions remain owned by the canonical authority.',facts:[{label:'Status',value:q.status||'UNKNOWN'},{label:'Next step',value:q.label||'OPEN'},{label:'Authority',value:ws.authority||'Canonical authority'},{label:'Resource',value:q.resourceId?`#${q.resourceId}`:'Platform scope'}],actionLabel:'OPEN WORKSPACE',onAction:()=>openWorkItem(q)})}));
  box.querySelector('#openCertification')?.addEventListener('click',()=>navigate('certification'));
  box.querySelectorAll('[data-explorer-tab]').forEach(tab=>tab.addEventListener('click',()=>{box.querySelectorAll('[data-explorer-tab]').forEach(x=>x.classList.toggle('active',x===tab));box.querySelectorAll('.control-area').forEach(x=>x.classList.toggle('explorer-hidden',x.id!==`command-category-${tab.dataset.explorerTab}`));box.querySelector(`#command-category-${tab.dataset.explorerTab}`)?.scrollIntoView({behavior:'smooth',block:'start'})}));
  const first=box.querySelector('.control-area');box.querySelectorAll('.control-area').forEach(x=>x.classList.toggle('explorer-hidden',x!==first));
 }catch(e){
  box.innerHTML=`<section class="card section error-state"><div class="eyebrow">CONTROL CENTER ERROR</div><h2>The platform situation could not be composed.</h2><p class="sub">No platform state was changed. The error is surfaced instead of replacing canonical data with defaults.</p><div class="notice">${escapeHtml(e.message||'Control Center unavailable')}</div><div class="actions"><button class="btn primary" id="retryCommandCenter">RETRY</button><button class="btn muted" id="openSystemHealth">OPEN SYSTEM HEALTH</button></div></section>`;
  box.querySelector('#retryCommandCenter')?.addEventListener('click',()=>navigate('overview'));box.querySelector('#openSystemHealth')?.addEventListener('click',()=>openWorkItem({action:'system-health'}));
 }
}
